اکنون، می‌توانید متغیر محیطی را در برنامه خود خوانده و به دیتابیس متصل شوید؛ در ادامه، یک قطعه کد مثال برای
اتصال به دیتابیس با استفاده از فریم‌ورک
express
برای شما، قرار گرفته است:

```
const express = require('express');
const { Pool } = require('pg');

const app = express();

const dbURI = process.env.PG_URI;

const pool = new Pool({
connectionString: dbURI,
});

pool.connect((err) => {
if (err) {
console.error('Error connecting to PostgreSQL database:', err);
app.locals.dbConnected = false;
return;
}
console.log('Connected to PostgreSQL database successfully');
app.locals.dbConnected = true;
});

app.get('/', (req, res) => {
res.send(app.locals.dbConnected ? 'Connection to database successful.' : 'Error connecting to database.');
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
console.log(\`server is running on port \${PORT}\`);
});

process.on('SIGINT', () => {
pool.end();
console.log('Database connection closed');
process.exit();
});
```

```
const express = require('express');
const { Pool } = require('pg');

const app = express();

const pool = new Pool({
user: process.env.DB_USER,
host: process.env.DB_HOST,
database: process.env.DB_NAME,
password: process.env.DB_PASS,
port: process.env.DB_PORT,
max: 20, // maximum number of connections in the pool
idleTimeoutMillis: 30000, // how long a client is allowed to remain idle before being closed
connectionTimeoutMillis: 2000, // how long to wait for a connection to be established
});

pool.connect((err) => {
if (err) {
console.error('Error connecting to PostgreSQL database:', err);
app.locals.dbConnected = false;
return;
}
console.log('Connected to PostgreSQL database successfully');
app.locals.dbConnected = true;
});

app.get('/', (req, res) => {
res.send(app.locals.dbConnected ? 'Connection to database successful.' : 'Error connecting to database.');
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
console.log(\`server is running on port \${PORT}\`);
});

process.on('SIGINT', () => {
pool.end();
console.log('Database connection closed');
process.exit();
});
```

