package main

import (
"context"
"fmt"
"log"
"os"

"github.com/elastic/go-elasticsearch/v8"
)

func main() {
// Get Elasticsearch configuration from environment variables
esURI := os.Getenv("ELASTICSEARCH_URI")
esUsername := os.Getenv("ELASTICSEARCH_USERNAME")
esPassword := os.Getenv("ELASTICSEARCH_PASSWORD")

if esURI == "" || esUsername == "" || esPassword == "" {
log.Fatal("Environment variables ELASTICSEARCH_URI, ELASTICSEARCH_USERNAME, and ELASTICSEARCH_PASSWORD must be set")
}

// Define the Elasticsearch connection configuration
esConfig := elasticsearch.Config{
Addresses: []string{
esURI,
},
Username: esUsername,
Password: esPassword,
}

// Create a new Elasticsearch client
es, err := elasticsearch.NewClient(esConfig)
if err != nil {
log.Fatalf("Error creating the Elasticsearch client: %s", err)
}

// Test the connection
res, err := es.Info()
if err != nil {
log.Fatalf("Error getting Elasticsearch info: %s", err)
}
defer res.Body.Close()

// Print the response
if res.IsError() {
log.Fatalf("Elasticsearch returned an error: %s", res.String())
}

fmt.Println("Connected to Elasticsearch successfully!")
fmt.Println(res.String())
}
```

برای اتصال به دیتابیس MongoDB در برنامه‌های go، در ابتدا باید ماژول مربوط به آن را با اجرای دستور زیر، نصب کنید:

```
go get go.mongodb.org/mongo-driver/mongo
```

پس از آن، کافیست تا
اطلاعات مربوط به دیتابیس خود را
به متغیرهای محیطی برنامه خود، اضافه کنید؛ به عنوان مثال:

```
MONGODB_URI="mongodb://root:cytAXXy458bz5iBO3Sm7xw8w@fitz-roy.liara.cloud:30219/my-app?authSource=admin"
```

در نهایت، می‌توانید با استفاده از قطعه کد زیر، به دیتابیس خود، متصل شوید:

```
package main

import (
"context"
"fmt"
"os"

"go.mongodb.org/mongo-driver/bson"
"go.mongodb.org/mongo-driver/mongo"
"go.mongodb.org/mongo-driver/mongo/options"
)

func main() {
// Get the MongoDB URI from the environment variable
uri := os.Getenv("MONGODB_URI")
if uri == "" {
panic("MONGODB_URI environment variable is not set")
}

// Use the SetServerAPIOptions() method to set the Stable API version to 1
serverAPI := options.ServerAPI(options.ServerAPIVersion1)
opts := options.Client().ApplyURI(uri).SetServerAPIOptions(serverAPI)

// Create a new client and connect to the server
client, err := mongo.Connect(context.TODO(), opts)
if err != nil {
panic(err)
}
defer func() {
if err = client.Disconnect(context.TODO()); err != nil {
panic(err)
}
}()

// Send a ping to confirm a successful connection
var result bson.M
if err := client.Database("admin").RunCommand(context.TODO(), bson.D{{Key: "ping", Value: 1}}).Decode(&result); err != nil {
panic(err)
}
fmt.Println("Pinged your deployment. You successfully connected to MongoDB!")
}
```

```
package main

import (
"database/sql"
"fmt"
"log"
"net/http"
"os"

_ "github.com/denisenkom/go-mssqldb"
)

var db *sql.DB

func main() {
// Get the DB_URI from environment variables
dbURI := os.Getenv("DB_URI")
if dbURI == "" {
log.Fatal("DB_URI environment variable is not set")
}

// Open the database connection with the MSSQL URI
var err error
db, err = sql.Open("sqlserver", dbURI)
if err != nil {
log.Fatalf("Failed to open database connection: %v", err)
}

// Set connection pool parameters
db.SetMaxOpenConns(10) // Maximum number of open connections
db.SetMaxIdleConns(5) // Maximum number of idle connections
db.SetConnMaxIdleTime(0) // No timeout for idle connections

// Verify connection
if err := db.Ping(); err != nil {
log.Fatalf("Failed to ping database: %v", err)
}
log.Println("Connected to database successfully!")

// Set up HTTP server
http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
if err := db.Ping(); err != nil {
fmt.Fprintf(w, "Database connection failed: %v", err)
} else {
fmt.Fprintln(w, "Database connection successful!")
}
})

log.Println("Server is running on http://localhost:8080")
if err := http.ListenAndServe(":8080", nil); err != nil {
log.Fatalf("HTTP server failed: %v", err)
}
