'charset' => 'utf8mb4',
'collation' => 'utf8mb4_unicode_ci',
'prefix' => '',
'strict' => true,
'engine' => null,
]);

DB::connection($connection)->getPdo();
$results[$connection] = 'Connection successful';
} catch (\\Exception $e) {
$results[$connection] = 'Connection failed: ' . $e->getMessage();
}
}

return response()->json($results);
}
}
